import math


def _count_divisors(n):
    """Return number of positive divisors of n."""
    if n <= 0:
        return 0
    root = math.isqrt(n)
    count = 0
    for d in range(1, root + 1):
        if n % d == 0:
            if d * d == n:
                count += 1
            else:
                count += 2
    return count


def find_Divisor(x, y):
    """Write a python function to find the maximum occuring divisor in an interval.

    Return the integer in the inclusive interval [x, y] that has the
    greatest number of positive divisors. If several numbers tie, the
    smallest such number is returned.

    The interval bounds are normalized so order does not matter and
    values below 1 are clamped to 1.
    """
    if x > y:
        x, y = y, x
    if y < 1:
        raise ValueError("interval must contain a positive integer")
    if x < 1:
        x = 1
    best = x
    best_count = _count_divisors(x)
    for n in range(x + 1, y + 1):
        c = _count_divisors(n)
        if c > best_count:
            best_count = c
            best = n
    return best
